async function activateConversation(c){if(!c||guardConversationSwitch())return;saveCurrentConversation();if(c.projectSpaceId&&state.projectSpaces.some(p=>p.id===c.projectSpaceId)&&state.activeProjectId!==c.projectSpaceId){await activateProjectSpace(c.projectSpaceId,'stay')}if(c.archived){c.archived=false;c.updatedAt=Date.now()}state.activeConversationId=c.id;setMode(c.mode==='work'?'work':'chat');const recovery=recoverInterruptedMessages(c.messages||[]);state.messages=recovery.messages;if(c.storageTrimmed){state.messages.unshift({role:'system',content:'Upozornění: kvůli limitu místního úložiště nebyla obnovena celá starší historie této konverzace.'});c.storageTrimmed=false}renderMessages();persist();setView('chat');$('viewTitle').textContent=c.title||'Konverzace';}
function renderPinnedChats(){const host=$('pinnedChats');if(!host)return;host.replaceChildren();const english=document.documentElement.lang==='en';const pinned=state.conversations.filter(c=>c.pinned&&!c.archived).sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));const count=$('pinnedChatsCount');if(count){count.textContent=pinned.length?String(pinned.length):'';count.hidden=!pinned.length;count.title=english?`${pinned.length} saved chats`:`${pinned.length} uložených chatů`;}const list=pinned.slice(0,12);if(!list.length){const empty=document.createElement('div');empty.className='sidebar-collection-empty';empty.textContent=english?'Pinned chats stay here for quick access. Pin one from its ⋯ menu.':'Připnuté chaty tu zůstanou po ruce. Připneš je přes nabídku ⋯.';host.appendChild(empty);return}for(const c of list){const row=document.createElement('div');row.className='sidebar-collection-row pinned-chat-row';const open=document.createElement('button');open.type='button';open.className='sidebar-collection-open';open.textContent=c.title|| (english?'Conversation':'Konverzace');open.title=c.title||'';open.onclick=()=>activateConversation(c);const unpin=document.createElement('button');unpin.type='button';unpin.className='sidebar-collection-remove';unpin.textContent='×';unpin.title=english?'Unpin chat':'Odepnout chat';unpin.setAttribute('aria-label',unpin.title);unpin.onclick=()=>{if(guardConversationSwitch())return;c.pinned=false;persist();renderHistory()};row.append(open,unpin);host.appendChild(row)}}
function renderProjectSpaces(){const sidebar=$('sidebarProjectList'),grid=$('projectWorkspaceGrid'),select=$('agentProjectSelect');const spaces=Array.isArray(state.projectSpaces)?state.projectSpaces:[];if(select){const keep=state.activeProjectId||'';select.replaceChildren();const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent=document.documentElement.lang==='en'?'Choose a project…':'Vyber projekt…';select.appendChild(placeholder);for(const project of spaces){const option=document.createElement('option');option.value=project.id;option.textContent=project.name;select.appendChild(option)}select.value=spaces.some(p=>p.id===keep)?keep:''}const workSelect=$('workProjectSelect');if(workSelect){const keep=state.activeProjectId||'';workSelect.replaceChildren();const placeholder=document.createElement('option');placeholder.value='';placeholder.textContent=document.documentElement.lang==='en'?'Choose project':'Vyber projekt';workSelect.appendChild(placeholder);for(const project of spaces){const option=document.createElement('option');option.value=project.id;option.textContent=project.name;workSelect.appendChild(option)}workSelect.value=spaces.some(p=>p.id===keep)?keep:''}const renderList=(host,compact)=>{if(!host)return;host.replaceChildren();if(!spaces.length){const empty=document.createElement('div');empty.className='sidebar-collection-empty';empty.textContent=document.documentElement.lang==='en'?'No projects yet. Add one with +.':'Zatím žádné projekty. Přidej první přes +.';host.appendChild(empty);return}for(const project of spaces){const row=document.createElement(compact?'div':'article');row.className=compact?'sidebar-collection-row project-sidebar-row':'project-space-card';if(!compact){const heading=document.createElement('div');heading.className='project-space-card-head';const icon=document.createElement('span');icon.className='project-space-icon';icon.textContent='▱';const title=document.createElement('b');title.textContent=project.name;heading.append(icon,title);const folder=document.createElement('small');folder.textContent=project.folderName||'';const active=document.createElement('span');active.className='project-space-status';active.textContent=state.activeProjectId===project.id&&state.folder?(document.documentElement.lang==='en'?'Connected':'Připojeno'):(document.documentElement.lang==='en'?'Reconnect':'Klikni pro připojení');const open=document.createElement('button');open.type='button';open.className='primary project-space-open';open.textContent=document.documentElement.lang==='en'?'Open project':'Otevřít projekt';open.onclick=()=>activateProjectSpace(project.id,'chat');const code=document.createElement('button');code.type='button';code.className='secondary project-space-code';code.textContent=document.documentElement.lang==='en'?'Open Code':'Otevřít Code';code.onclick=()=>activateProjectSpace(project.id,'code');const actions=document.createElement('div');actions.className='project-space-actions';const rename=document.createElement('button');rename.type='button';rename.className='secondary';rename.textContent=document.documentElement.lang==='en'?'Rename':'Přejmenovat';rename.onclick=()=>renameProjectSpace(project.id);const remove=document.createElement('button');remove.type='button';remove.className='secondary danger';remove.textContent=document.documentElement.lang==='en'?'Remove':'Odebrat';remove.onclick=()=>removeProjectSpace(project.id);actions.append(rename,remove);row.append(heading,folder,active,open,code,actions)}else{const open=document.createElement('button');open.type='button';open.className='sidebar-collection-open project-sidebar-open';open.textContent=project.name;open.title=project.folderName||project.name;open.onclick=()=>activateProjectSpace(project.id,'chat');const stateDot=document.createElement('span');stateDot.className='project-sidebar-dot'+(state.activeProjectId===project.id&&state.folder?' active':'');const options=document.createElement('button');options.type='button';options.className='sidebar-collection-remove';options.textContent='⋯';options.title=document.documentElement.lang==='en'?'Project options':'Možnosti projektu';options.setAttribute('aria-label',options.title);const menu=document.createElement('div');menu.className='project-sidebar-menu hidden';const rename=document.createElement('button');rename.type='button';rename.textContent=document.documentElement.lang==='en'?'Rename':'Přejmenovat';rename.onclick=()=>{menu.classList.add('hidden');renameProjectSpace(project.id)};const remove=document.createElement('button');remove.type='button';remove.className='danger';remove.textContent=document.documentElement.lang==='en'?'Remove':'Odebrat';remove.onclick=()=>{menu.classList.add('hidden');removeProjectSpace(project.id)};menu.append(rename,remove);options.onclick=()=>menu.classList.toggle('hidden');row.append(stateDot,open,options,menu)}host.appendChild(row)}};renderList(sidebar,true);renderList(grid,false);}
async function loadProjectSpaces(){try{state.projectSpaces=await window.aurora.listProjectSpaces();if(!Array.isArray(state.projectSpaces))state.projectSpaces=[];if(state.lastProjectId&&!state.projectSpaces.some(p=>p.id===state.lastProjectId))state.lastProjectId=null;renderProjectSpaces()}catch(error){console.warn('Project spaces unavailable:',error);state.projectSpaces=[];renderProjectSpaces()}}
async function activateProjectSpace(id,destination='chat'){if(state.sending||state.agentRunning||state.agentPreparing||state.workspaceBusy){toast(document.documentElement.lang==='en'?'Finish the current operation before switching projects.':'Před přepnutím projektu dokonči běžící úlohu.');return null}state.workspaceBusy=true;try{const picked=await window.aurora.selectProjectSpace(id);if(!picked)return null;state.activeProjectId=picked.project.id;state.lastProjectId=picked.project.id;state.folder={path:picked.path,name:picked.name};state.projectFolder=state.folder;const scan=await window.aurora.scanProject({maxFiles:100});state.projectFiles=scan.files;const pathLabel=$('scopePath');if(pathLabel)pathLabel.textContent=picked.path;const status=$('agentQueue');if(status)status.innerHTML=`<div class="eyebrow">PROJEKT PŘIPOJEN</div><b>${esc(picked.name)}</b><span>${scan.files.length} textových souborů připravených pro bezpečnou analýzu</span><div class="file-list">${scan.files.slice(0,12).map(f=>`<div>${esc(f.path)}</div>`).join('')}</div><p class="muted">Zatím pouze čtení. Žádné soubory nebyly změněny.</p>`;persist();renderProjectSpaces();if($('composerHint'))$('composerHint').textContent=`Projekt: ${picked.name} · složka připojena`;toast(`Projekt ${picked.name} je připojen · ${scan.files.length} souborů`);if(destination==='code'){setMode('work');setView('chat')}else if(destination==='chat')setView('chat');return picked}catch(error){toast('Projekt se nepodařilo otevřít: '+error.message);return null}finally{state.workspaceBusy=false}}
async function createProjectSpace(openCode=false,keepWorkspaceLock=false){if(state.sending||state.agentRunning||state.agentPreparing||(state.workspaceBusy&&!keepWorkspaceLock)){toast('Dokonči nejprve právě probíhající úlohu.');return null}const name=prompt(document.documentElement.lang==='en'?'Project name (optional; folder name will be used if empty)':'Název projektu (volitelné; jinak se použije název složky)','');if(name===null)return null;if(!keepWorkspaceLock)state.workspaceBusy=true;try{const created=await window.aurora.createProjectSpace(name);if(!created)return null;state.projectSpaces=await window.aurora.listProjectSpaces();state.activeProjectId=created.project.id;state.lastProjectId=created.project.id;state.folder={path:created.path,name:created.name};state.projectFolder=state.folder;const scan=await window.aurora.scanProject({maxFiles:100});state.projectFiles=scan.files;const scope=$('scopePath');if(scope)scope.textContent=created.path;persist();renderProjectSpaces();toast(created.created===false?`Projekt ${created.name} už existuje a byl připojen`:`Projekt ${created.name} byl přidán`);if(openCode)setView('agent');else setView('projects');return created}catch(error){toast('Vytvoření projektu selhalo: '+error.message);return null}finally{if(!keepWorkspaceLock)state.workspaceBusy=false}}
async function renameProjectSpace(id){const item=state.projectSpaces.find(p=>p.id===id);if(!item||state.workspaceBusy||state.sending||state.agentRunning||state.agentPreparing)return;const en=document.documentElement.lang==='en';const name=prompt(en?'New project name':'Nový název projektu',item.name);if(name===null||!name.trim())return;state.workspaceBusy=true;try{await window.aurora.renameProjectSpace({id,name});state.projectSpaces=await window.aurora.listProjectSpaces();if(state.activeProjectId===id&&state.folder)state.folder.name=name.trim().slice(0,80);persist();renderProjectSpaces();toast(en?'Project renamed.':'Název projektu byl změněn.')}catch(error){toast(error.message)}finally{state.workspaceBusy=false}}
async function removeProjectSpace(id){const item=state.projectSpaces.find(p=>p.id===id);if(!item)return;if(state.workspaceBusy||state.sending||state.agentRunning||state.agentPreparing){toast(document.documentElement.lang==='en'?'Finish the active task before removing a project.':'Před odebráním projektu dokonči aktivní úlohu.');return}const en=document.documentElement.lang==='en';const question=en?`Remove “${item.name}” from Aurora? The folder and files on disk will NOT be deleted.`:`Odebrat „${item.name}“ z Aurory? Složka ani soubory na disku se NESMAŽOU.`;if(!confirm(question))return;state.workspaceBusy=true;try{await window.aurora.removeProjectSpace(id);state.projectSpaces=await window.aurora.listProjectSpaces();for(const c of state.conversations){if(c.projectSpaceId===id){c.projectSpaceId=null;c.project=false}}if(state.activeProjectId===id){state.activeProjectId=null;state.folder=null;state.projectFolder=null;state.projectFiles=[]}if(state.lastProjectId===id)state.lastProjectId=null;persist();renderProjectSpaces();renderHistory();toast(en?'Project removed from Aurora; files remain on disk.':'Projekt byl odebrán z Aurory; soubory zůstaly na disku.')}catch(error){toast(error.message)}finally{state.workspaceBusy=false}}
function renderArchiveAndProjects(){const archived=state.conversations.filter(c=>c.archived);const projects=state.conversations.filter(c=>c.project&&!c.archived);const count=$('archiveCount');if(count)count.textContent=`${archived.length} dokončených ${archived.length===1?'konverzace':'konverzací'}`;const archive=$('archiveList');if(archive){archive.replaceChildren();if(!archived.length){const e=document.createElement('div');e.className='empty-state';e.textContent='Zatím tu nejsou žádné dokončené chaty. V seznamu nedávných klikni na ⋯ u konverzace.';archive.appendChild(e)}for(const c of archived)archive.appendChild(createConversationRow(c,'archived'))}const projectList=$('projectChatList');if(projectList){projectList.replaceChildren();$('projectChatCount').textContent=`${projects.length} chatů`;if(!projects.length){const e=document.createElement('div');e.className='empty-state';e.textContent='Zatím žádný chat není označený jako projekt. V seznamu chatů klikni na ⋯ a vyber „Přidat do projektů“.';projectList.appendChild(e)}for(const c of projects)projectList.appendChild(createConversationRow(c,'projects'))}}
function createConversationRow(c,context){const row=document.createElement('article');row.className='conversation-row';const open=document.createElement('button');open.type='button';open.className='conversation-open';const title=document.createElement('b');title.textContent=c.title||'Konverzace';const meta=document.createElement('small');meta.textContent=`${(c.messages||[]).filter(m=>m.role==='user').length} zpráv uživatele · ${new Date(c.updatedAt||Date.now()).toLocaleDateString('cs-CZ')}`;open.append(title,meta);open.onclick=()=>activateConversation(c);if(context==='archived'){const restore=document.createElement('button');restore.type='button';restore.className='conversation-menu';restore.textContent='Obnovit';restore.onclick=()=>{c.archived=false;c.updatedAt=Date.now();persist();renderHistory();renderArchiveAndProjects()};row.append(open,restore);return row}const action=document.createElement('button');action.type='button';action.className='conversation-menu';action.textContent='⋯';action.title='Možnosti konverzace';action.setAttribute('aria-label','Možnosti konverzace: '+c.title);const menu=document.createElement('div');menu.className='conversation-action-menu hidden';const pin=document.createElement('button');pin.type='button';pin.textContent=c.pinned?'Odepnout z Uložených':'Připnout do Uložených';pin.onclick=()=>{c.pinned=!c.pinned;persist();renderHistory();renderArchiveAndProjects()};const project=document.createElement('button');project.type='button';project.textContent=c.project?'Odebrat z projektových chatů':'Přidat do projektových chatů';project.onclick=()=>{if(guardConversationSwitch())return;if(!c.project&&!state.activeProjectId&&state.projectSpaces.length===0){toast('Nejdřív přidej projektovou složku.');setView('projects');return}c.project=!c.project;if(c.project&&state.activeProjectId)c.projectSpaceId=state.activeProjectId;if(!c.project)c.projectSpaceId=null;persist();renderHistory();renderArchiveAndProjects()};const moveLabel=document.createElement('label');moveLabel.className='history-project-move';moveLabel.textContent='Projekt chatu';const move=document.createElement('select');move.setAttribute('aria-label','Přiřadit chat k projektu');const none=document.createElement('option');none.value='';none.textContent='Bez projektu';move.appendChild(none);for(const item of state.projectSpaces||[]){const option=document.createElement('option');option.value=item.id;option.textContent=item.name;move.appendChild(option)}move.value=c.projectSpaceId||'';move.onchange=()=>{if(guardConversationSwitch()){move.value=c.projectSpaceId||'';return}c.projectSpaceId=move.value||null;c.project=!!c.projectSpaceId;persist();renderHistory();renderArchiveAndProjects()};moveLabel.appendChild(move);const rename=document.createElement('button');rename.type='button';rename.textContent='Přejmenovat';rename.onclick=()=>{const title=prompt('Nový název konverzace',c.title||'');if(title&&title.trim()){c.title=title.trim().slice(0,160);persist();renderHistory();renderArchiveAndProjects()}};const remove=document.createElement('button');remove.type='button';remove.className='danger';remove.textContent='Smazat konverzaci';remove.onclick=()=>{if(guardConversationSwitch())return;if(!confirm(`Opravdu smazat konverzaci „${c.title||'Konverzace'}“?`))return;state.conversations=state.conversations.filter(item=>item.id!==c.id);if(state.activeConversationId===c.id){state.activeConversationId=null;state.messages=[];renderMessages();setView('chat')}persist();renderHistory();renderArchiveAndProjects()};const archive=document.createElement('button');archive.type='button';archive.textContent=c.archived?'Obnovit mezi nedávné':'Přesunout do archivu';archive.onclick=()=>{if(guardConversationSwitch())return;c.archived=!c.archived;if(c.archived){c.project=false;c.pinned=false}persist();renderHistory();renderArchiveAndProjects()};menu.append(pin,project,moveLabel,archive);action.onclick=()=>menu.classList.toggle('hidden');row.append(open,action,menu);return row}
function setMode(mode){
 const next=mode==='work'?'work':'chat';
 if((state.agentRunning||state.agentPreparing)&&state.mode!==next){toast(document.documentElement.lang==='en'?'Finish the active Work task before changing modes.':'Nejdřív dokonči pracovní úlohu.');return false}
 state.mode=next;
 const main=document.querySelector('.main');if(main)main.dataset.mode=next;
 const chatButton=$('chatModeToggle'),workButton=$('workModeToggle');
 if(chatButton){chatButton.classList.toggle('active',next==='chat');chatButton.setAttribute('aria-selected',String(next==='chat'))}
 if(workButton){workButton.classList.toggle('active',next==='work');workButton.setAttribute('aria-selected',String(next==='work'))}
 const activeConversation=state.conversations.find(c=>c.id===state.activeConversationId);if(activeConversation)activeConversation.mode=next;
 const prompt=$('prompt');if(prompt)prompt.placeholder=next==='work'?(document.documentElement.lang==='en'?'Describe what you want to build or change…':'Napiš, co chceš vytvořit nebo upravit…'):(document.documentElement.lang==='en'?'Ask anything…':'Napiš zprávu…');
 const welcome=$('welcome');if(welcome){const heading=welcome.querySelector('h1'),sub=welcome.querySelector('p');if(heading)heading.innerHTML=next==='work'?(document.documentElement.lang==='en'?'What are we working on?':'Na čem budeme pracovat?'):'Ahoj, jsem <span>Aurora</span>';if(sub)sub.textContent=next==='work'?(document.documentElement.lang==='en'?'Same chat, with project context and safe file changes when you need them.':'Stejný chat, jen s kontextem projektu a bezpečnými úpravami souborů, když je potřebuješ.'):(document.documentElement.lang==='en'?'Your local AI assistant. What can I help with?':'Tvá lokální AI asistentka. S čím ti dnes pomohu?')}
 const workControl=$('workProjectControl');if(workControl)workControl.setAttribute('aria-hidden',String(next!=='work'));const hint=$('composerHint');if(hint&&!state.agentRunning&&!state.sending)hint.textContent=next==='work'?(state.folder?(document.documentElement.lang==='en'?'Work project: '+state.folder.name:'Pracovní projekt: '+state.folder.name):(document.documentElement.lang==='en'?'Choose a project to start working':'Vyber projekt a můžeš začít pracovat')):(state.autoRoute?'Auto · model vyberu podle zadání':state.model?'Model: '+state.model:'Vyber lokální model v horní liště.');
 persist();return true;
}
function setView(view,options={}){
 if(view==='agent'){setMode('work');view='chat'}
 state.view=view;const main=document.querySelector('.main');if(main)main.dataset.view=view;
 const group=Object.prototype.hasOwnProperty.call(options,'navGroup')?options.navGroup:(NAV_GROUP_FOR_VIEW[view]||null);setNavExpanded(group,!!group);syncNavigation(view,group);
 ['chat','agent','models','performance','connect','tools','web','images','projects','memory','settings'].forEach(v=>{const el=$(v+'View');if(el){const visible=v===view&&v!=='agent';el.classList.toggle('hidden',!visible);el.setAttribute('aria-hidden',String(!visible));el.inert=!visible;if(visible&&!document.body.classList.contains('quiet-ui-effects')){el.classList.remove('view-entering');void el.offsetWidth;el.classList.add('view-entering');window.setTimeout(()=>el.classList.remove('view-entering'),280)}}});
 const activeConversation=state.conversations.find(c=>c.id===state.activeConversationId);$('viewTitle').textContent=view==='chat'?(activeConversation?.title||'Nová konverzace'):({models:'Model Hub',performance:'Výkon & runtime',connect:'Connect',tools:'Nástroje & integrace',web:'Internetový výzkum',images:'Vizuální engine',projects:'Projekty',memory:'Dokončené chaty',settings:'Nastavení'})[view];
 if(view==='models')renderModels();if(view==='performance'){refreshRuntime();renderTelemetry()}if(view==='connect'){refreshTools();refreshRobloxBridge?.()}if(view==='tools')refreshTools();if(view==='images')refreshComfyStatus();if(view==='settings'&&options.settingsCategory)setSettingsCategory(options.settingsCategory);if(view!=='chat')window.AuroraUI?.playSound?.('navigate');
}

document.querySelectorAll('.dash-minimize').forEach(button=>button.addEventListener('click',()=>{const card=button.closest('.dash-card');const collapsed=card.classList.toggle('is-collapsed');button.setAttribute('aria-expanded',String(!collapsed));button.textContent=collapsed?'+':'−';button.setAttribute('aria-label',(collapsed?'Rozbalit ':'Sbalit ')+(card.querySelector('.dash-title b')?.textContent||'panel'));}));
document.querySelectorAll('#mainNavigation .nav-group-toggle').forEach(button=>button.addEventListener('click',()=>{const group=button.dataset.navGroup;const container=button.closest('[data-nav-group-container]');const expanded=container?.classList.contains('expanded');if(state.view===button.dataset.view){setNavExpanded(group,!expanded);return}setView(button.dataset.view,{navGroup:group});}));
document.querySelectorAll('#mainNavigation .nav-child').forEach(button=>button.addEventListener('click',()=>{const group=button.closest('[data-nav-group-container]')?.dataset.navGroupContainer;const category=button.dataset.settingsCategoryTarget;setView(button.dataset.view,{navGroup:group,...(category?{settingsCategory:category}:{})});}));
document.querySelectorAll('#mainNavigation .nav:not(.nav-group-toggle)').forEach(button=>button.addEventListener('click',()=>setView(button.dataset.view,{navGroup:null})));
document.querySelectorAll('[data-view]').forEach(button=>{if(!button.closest('#mainNavigation')&&!button.classList.contains('nav'))button.addEventListener('click',()=>setView(button.dataset.view));});
