document.querySelectorAll('[data-history-filter]').forEach(b=>b.addEventListener('click',()=>{state.historyFilter=b.dataset.historyFilter;document.querySelectorAll('[data-history-filter]').forEach(x=>x.classList.toggle('active',x===b));renderHistory()}));document.querySelectorAll('[data-action="new-chat"]').forEach(b=>b.addEventListener('click',()=>$('newChat').click()));$('settingsBtn').onclick=()=>setView('settings',{settingsCategory:'personalization'});$('defaultWorkspace')?.addEventListener('click',()=>setView('projects'));$('openMemorySettings').onclick=()=>setView('memory');$('newChat').onclick=()=>{if(guardConversationSwitch())return;saveCurrentConversation();state.messages=[];state.activeConversationId=null;renderMessages();$('welcome').classList.remove('compact');$('messages').innerHTML='';$('prompt').focus();$('viewTitle').textContent='Nová konverzace';persist();setView('chat');$('viewTitle').textContent='Nová konverzace'};document.addEventListener('click',e=>{document.querySelectorAll('.conversation-action-menu').forEach(menu=>{if(!menu.parentElement?.contains(e.target))menu.classList.add('hidden')});const wrap=document.querySelector('.quick-model-wrap');if(wrap&&!wrap.contains(e.target)){$('quickModelMenu')?.classList.add('hidden');$('modelQuick')?.setAttribute('aria-expanded','false')}const effort=document.querySelector('.effort-picker');if(effort&&!effort.contains(e.target)){$('effortMenu')?.classList.add('hidden');$('effortToggle')?.setAttribute('aria-expanded','false')}});$('clearHistory').onclick=()=>{if(guardConversationSwitch())return;if(confirm('Opravdu smazat uloženou historii konverzací?')){state.history=[];state.conversations=[];state.activeConversationId=null;state.messages=[];renderMessages();persist();renderHistory()}};$('autoRoute').checked=state.autoRoute;$('autoRoute').disabled=true;$('refreshRuntime').onclick=refreshRuntime;$('refreshTools').onclick=refreshTools;$('refresh').onclick=()=>refreshStatus({notify:true});$('refreshModels').onclick=()=>refreshStatus({notify:true});$('hardwareRefresh').onclick=loadHardware;$('testOllama').onclick=()=>refreshStatus({notify:true});$('ollamaDownload').onclick=()=>{window.aurora.openOllama();toast('Otevírám oficiální stránku Ollama.')};$('unityDocs').onclick=()=>{window.aurora.openUnityDocs();};
$('auditGodot')?.addEventListener('click',async()=>{
 const btn=$('auditGodot');if(!btn)return;
 const english=document.documentElement.lang==='en';
 const labels=english?{checking:'Checking Godot project…',run:'Run Godot audit',waiting:'WAITING FOR PROJECT',notGodot:'NOT A GODOT PROJECT',errors:'AUDIT: ERRORS',warnings:'AUDIT: WARNINGS',done:'AUDIT COMPLETE',error:'ERROR',warning:'WARNING',info:'INFO',mainScene:'Main scene',scripts:'GDScript scripts',scenes:'scenes',resources:'resources',errorsCount:'Errors',warningsCount:'warnings',infoCount:'info',limit:'Scan limit reached; results may be incomplete.',noFindings:'No known patterns were found by this limited check.',noProject:'No project.godot file was found or it could not be read safely.',missingMain:'The configured main scene was not found.',unsafeMain:'The configured main scene path could not be safely verified.',largeMain:'The main scene exists but exceeds the read limit; its contents were skipped.',mainUnset:'No run/main_scene is configured.',missingResource:'Referenced resource was not found.',unsafeResource:'Resource points to a symbolic link, special file, or path that cannot be safely verified.',largeResource:'Resource exists but exceeds the content read limit; only file existence was checked.',unsafePath:'Resource path cannot be safely normalized.',emptyScript:'GDScript file is empty.',godot3Syntax:'This script may contain Godot 3 syntax that is incompatible with Godot 4. This is a heuristic.',godot4Syntax:'This script may contain Godot 4 syntax that is incompatible with Godot 3. This is a heuristic.',todo:'TODO/FIXME/HACK marker found.',fileLimit:'File exceeds the scan size limit and was skipped.',scanLimit:'Audit reached its file or entry limit; results may be incomplete.',note:'Read-only static heuristic check. Godot is not launched and GDScript is not parsed by the engine; this does not prove that the project imports or runs.'}:{checking:'Kontroluji Godot projekt…',run:'Provést Godot audit',waiting:'ČEKÁ NA PROJEKT',notGodot:'NENÍ GODOT PROJEKT',errors:'AUDIT: CHYBY',warnings:'AUDIT: VAROVÁNÍ',done:'AUDIT DOKONČEN',error:'CHYBA',warning:'VAROVÁNÍ',info:'INFO',mainScene:'Hlavní scéna',scripts:'GDScript',scenes:'scény',resources:'zdroje',errorsCount:'Chyby',warningsCount:'varování',infoCount:'informace',limit:'Byl dosažen limit skenování; výsledek může být neúplný.',noFindings:'Nebyly nalezeny žádné známé vzory této omezené kontroly.',noProject:'Soubor project.godot nebyl nalezen nebo není bezpečně čitelný.',missingMain:'Nastavená hlavní scéna nebyla nalezena.',unsafeMain:'Cestu k hlavní scéně nelze bezpečně ověřit.',largeMain:'Hlavní scéna existuje, ale přesahuje limit čtení; její obsah byl vynechán.',mainUnset:'Není nastavena run/main_scene.',missingResource:'Odkazovaný zdroj nebyl nalezen.',unsafeResource:'Zdroj míří na symbolický odkaz, speciální soubor nebo cestu, kterou nelze bezpečně ověřit.',largeResource:'Zdroj existuje, ale jeho obsah přesahuje limit čtení; ověřena byla pouze existence souboru.',unsafePath:'Cestu ke zdroji nelze bezpečně normalizovat.',emptyScript:'GDScript soubor je prázdný.',godot3Syntax:'Skript může obsahovat syntaxi Godot 3, která není kompatibilní s Godot 4. Jde o heuristiku.',godot4Syntax:'Skript může obsahovat syntaxi Godot 4, která není kompatibilní s Godot 3. Jde o heuristiku.',todo:'Nalezena značka TODO/FIXME/HACK.',fileLimit:'Soubor přesahuje limit velikosti a byl vynechán.',scanLimit:'Audit dosáhl limitu souborů nebo položek; výsledek může být neúplný.',note:'Read-only statická heuristická kontrola. Godot se nespouští a GDScript neparsuje skutečný engine; výsledek nepotvrzuje, že projekt lze importovat nebo spustit.'};
 btn.disabled=true;btn.textContent=labels.checking;
 try{
  if(!state.projectFolder)await chooseFolder();
  if(!state.projectFolder)return;
  const report=await window.aurora.godotAudit();
  const findings=Array.isArray(report.findings)?report.findings:[];
  $('godotStatus').textContent=!report.isGodot?labels.notGodot:report.counts?.error?labels.errors:report.counts?.warning?labels.warnings:labels.done;
  const severity=english?{error:'ERROR',warning:'WARNING',info:'INFO'}:{error:'CHYBA',warning:'VAROVÁNÍ',info:'INFO'};
  const messageFor=item=>{
   if(!english)return item.message;
   const messageMap={NO_PROJECT_FILE:labels.noProject,MISSING_MAIN_SCENE:`${labels.missingMain} (${report.mainScene||'res://…'})`,UNSAFE_MAIN_SCENE:labels.unsafeMain,MAIN_SCENE_SIZE_LIMIT:labels.largeMain,MAIN_SCENE_NOT_SET:labels.mainUnset,MISSING_RESOURCE:labels.missingResource,UNSAFE_RESOURCE:labels.unsafeResource,RESOURCE_SIZE_LIMIT:labels.largeResource,UNSAFE_RESOURCE_PATH:labels.unsafePath,EMPTY_SCRIPT:labels.emptyScript,GODOT3_SYNTAX:labels.godot3Syntax,GODOT4_SYNTAX:labels.godot4Syntax,TODO_MARKER:item.message,FILE_SKIPPED_SIZE:labels.fileLimit,SCAN_LIMIT_REACHED:labels.scanLimit};
   if(messageMap[item.code])return messageMap[item.code];
   if(item.code==='UNSAFE_RESOURCE_PATH')return labels.unsafePath;
   return item.message;
  };
  const names=english?{NO_PROJECT_FILE:'PROJECT_FILE_MISSING',MISSING_MAIN_SCENE:'MAIN_SCENE_MISSING',UNSAFE_MAIN_SCENE:'MAIN_SCENE_UNSAFE',MAIN_SCENE_SIZE_LIMIT:'MAIN_SCENE_TOO_LARGE',MAIN_SCENE_NOT_SET:'MAIN_SCENE_NOT_SET',MISSING_RESOURCE:'RESOURCE_MISSING',UNSAFE_RESOURCE:'RESOURCE_UNSAFE',RESOURCE_SIZE_LIMIT:'RESOURCE_TOO_LARGE',UNSAFE_RESOURCE_PATH:'RESOURCE_PATH_UNSAFE',EMPTY_SCRIPT:'EMPTY_SCRIPT',GODOT3_SYNTAX:'GODOT3_SYNTAX',GODOT4_SYNTAX:'GODOT4_SYNTAX',TODO_MARKER:'TODO_MARKER',FILE_SKIPPED_SIZE:'FILE_TOO_LARGE',SCAN_LIMIT_REACHED:'SCAN_LIMIT'}:{};
  const list=report.limitReached?`<p class="muted">${esc(labels.limit)}</p>`:'';
  const noFindings=`<p>${esc(labels.noFindings)}</p>`;
  $('godotReport').innerHTML=`<b>${esc(report.projectName|| (english?'Godot project':'Godot projekt'))} · Godot ${esc(report.engineVersion||'—')}</b><p>${esc(labels.mainScene)}: ${esc(report.mainScene||'—')} · ${esc(labels.scripts)}: ${Number(report.scannedScripts)||0} · ${esc(labels.scenes)}: ${Number(report.scannedScenes)||0} · ${esc(labels.resources)}: ${Number(report.scannedResources)||0}</p><p>${esc(labels.errorsCount)}: ${Number(report.counts?.error)||0} · ${esc(labels.warningsCount)}: ${Number(report.counts?.warning)||0} · ${esc(labels.infoCount)}: ${Number(report.counts?.info)||0}</p>${list}${findings.length?`<div class="unity-findings">${findings.slice(0,60).map(item=>`<div class="unity-finding"><b>[${esc(severity[item.severity]||item.severity)}] ${esc(names[item.code]||item.code)} · ${esc(item.file)}${item.line?':'+item.line:''}</b><code>${esc(messageFor(item))}</code></div>`).join('')}</div>`:noFindings}<small>${esc(labels.note)}</small>`;
 }catch(error){toast((english?'Godot audit: ':'Godot audit: ')+error.message)}finally{btn.disabled=false;btn.textContent=labels.run}
});

$('auditUnity').onclick=async()=>{const btn=$('auditUnity');btn.disabled=true;btn.textContent='Kontroluji…';try{if(!state.projectFolder)await chooseFolder();if(!state.projectFolder)return;const report=await window.aurora.unityAudit();lastUnityAuditReport=report;$('exportUnityAudit').disabled=false;const f=report.findings||[];const sev={error:'CHYBA',warning:'VAROVÁNÍ',info:'INFO'};$('unityStatus').textContent=report.counts.error?'AUDIT: CHYBY':report.counts.warning?'AUDIT: VAROVÁNÍ':'AUDIT DOKONČEN';$('unityReport').innerHTML=`<b>Statický audit projektu</b><p>Skriptů C#: ${report.scannedScripts} · souborů v Assets: ${report.scannedAssets} · balíčků: ${report.packageCount}</p><p>Chyby: ${report.counts.error} · varování: ${report.counts.warning} · informace: ${report.counts.info}</p>${report.limitReached?'<p class="muted">Byl dosažen limit počtu procházených položek; výsledek může být neúplný.</p>':''}${f.length?`<div class="unity-findings">${f.slice(0,100).map(x=>`<div class="unity-finding"><b>[${esc(sev[x.severity]||x.severity)}] ${esc(x.code)} · ${esc(x.file)}${x.line?':'+x.line:''}</b><code>${esc(x.message)}</code></div>`).join('')}</div>`:'<p>Nebyly nalezeny žádné známé vzory z této omezené kontroly.</p>'}<small>${esc(report.note)}</small>`}catch(e){toast('Statický audit: '+e.message)}finally{btn.disabled=false;btn.textContent='Spustit statický audit'}};
$('exportUnityAudit').onclick=async()=>{if(!lastUnityAuditReport){toast('Nejdřív spusť statický audit.');return}const btn=$('exportUnityAudit');btn.disabled=true;try{const result=await window.aurora.exportUnityAudit(lastUnityAuditReport);if(!result.cancelled)toast(`Audit exportován (${result.format.toUpperCase()}): ${result.path}`)}catch(e){toast('Export auditu selhal: '+e.message)}finally{btn.disabled=!lastUnityAuditReport}};
$('inspectUnity').onclick=async()=>{const btn=$('inspectUnity');btn.disabled=true;btn.textContent='Analyzuji…';try{if(!state.projectFolder)await chooseFolder();if(!state.projectFolder)return;const [info,diag]=await Promise.all([window.aurora.unityInfo(),window.aurora.unityDiagnostics()]);$('unityStatus').textContent=info.isUnity?'UNITY PROJEKT NALEZEN':'ČÁSTEČNÝ / NEUNITY';const findings=diag.findings||[];$('unityReport').innerHTML=`<b>${info.isUnity?'Unity '+esc(info.version):'Unity struktura nebyla kompletně rozpoznána'}</b><p>Assets: ${info.hasAssets?'ano':'ne'} · ProjectSettings: ${info.hasProjectSettings?'ano':'ne'} · manifest: ${info.hasManifest?'ano':'ne'}</p><p>Balíčky (${info.packages.length}): ${info.packages.map(esc).join(', ')||'nenalezeny'}</p><p>Prohledané logy: ${diag.scanned.length?diag.scanned.map(esc).join(', '):'žádné .log soubory nenalezeny'}</p><div class="rule"></div><b>Nálezy v logu: ${findings.length}</b>${findings.length?`<div class="unity-findings">${findings.slice(0,25).map(f=>`<div class="unity-finding"><b>${esc(f.file)}:${f.line}</b><code>${esc(f.text)}</code></div>`).join('')}</div>`:'<p>Ve skenovaných logách nebyly nalezeny běžné výrazy chyb. To samo o sobě nepotvrzuje, že projekt je bez chyb.</p>'}<small>${esc(diag.note||'')}</small>`}catch(e){toast('Unity analýza: '+e.message)}finally{btn.disabled=false;btn.textContent='Analyzovat Unity projekt'}};
