const capcutButton=$('auditCapCut');
capcutButton?.addEventListener('click',async()=>{
 const button=capcutButton,english=document.documentElement.lang==='en';
 button.disabled=true;button.textContent=english?'Analyzing…':'Analyzuji…';
 try{
  if(!state.projectFolder)await chooseFolder();
  if(!state.projectFolder)return;
  const report=await window.aurora.capcutAudit();
  const findings=Array.isArray(report.findings)?report.findings:[];
  const count=report.summary||{};
  $('capcutStatus').textContent=(count.error||0)?(english?'AUDIT: ERRORS':'AUDIT: CHYBY'):(count.warning||0)?(english?'AUDIT: WARNINGS':'AUDIT: VAROVÁNÍ'):(english?'AUDIT COMPLETE':'AUDIT DOKONČEN');
  $('capcutReport').innerHTML=`<b>${esc(report.projectName||'CapCut project')}</b><p>${esc(report.timelineFile||'—')} · ${formatBytes(report.sizeBytes)} · ${esc(report.resolution||'—')} · ${esc(report.fps??'—')} FPS · ${Number(report.durationSeconds||0).toLocaleString('cs-CZ')} s</p><p>Stopy: ${Number(report.counts?.tracks)||0} · Segmenty: ${Number(report.counts?.segments)||0} · Média: ${Object.values(report.counts?.materials||{}).reduce((a,b)=>a+(Number(b)||0),0)}</p><p>Chyby: ${Number(count.error)||0} · Varování: ${Number(count.warning)||0} · Info: ${Number(count.info)||0}</p>${findings.length?`<div class="unity-findings">${findings.slice(0,40).map(item=>`<div class="unity-finding"><b>[${esc(item.severity)}] ${esc(item.code)}</b><code>${esc(item.message)}</code></div>`).join('')}</div>`:'<p>Audit nenalezl známé problémy v kontrolovaných polích.</p>'}<small>${esc(report.note||'Read-only CapCut audit.')}</small>`;
 }catch(error){$('capcutStatus').textContent=english?'AUDIT FAILED':'AUDIT SELHAL';toast('CapCut audit: '+error.message)}
 finally{button.disabled=false;button.textContent=english?'Analyze CapCut draft':'Analyzovat CapCut draft'}
});

const projectActionSelect=$('projectCheckAction');
async function loadProjectCheckControls(){
 if(!projectActionSelect)return;
 try{
  const result=await window.aurora.projectCheckActions();
  const actions=Array.isArray(result?.actions)?result.actions:[];
  projectActionSelect.innerHTML='<option value="">Vyber přednastavenou kontrolu…</option>'+actions.map(item=>`<option value="${esc(item.id)}">${esc(item.label)}${item.executesProjectScripts?' · vyžaduje potvrzení':''}</option>`).join('');
  const paths=await window.aurora.editorPaths();
  const pathLabel=[paths.godot?`Godot: ${paths.godot}`:'Godot: nenastaven',paths.unity?`Unity: ${paths.unity}`:'Unity: nenastaven'].join(' · ');
  if($('projectEditorPaths'))$('projectEditorPaths').textContent=pathLabel;
  if($('vscodeStatus'))$('vscodeStatus').textContent=paths.vscode?'VS CODE NASTAVEN':'EDITOR NENASTAVEN';
  if($('vscodePath'))$('vscodePath').textContent=paths.vscode||'Vyber Code.exe / Visual Studio Code executable.';
 }catch(error){if(projectActionSelect)projectActionSelect.innerHTML='<option value="">Kontroly nelze načíst</option>';toast('Projektové kontroly: '+error.message)}
}
loadProjectCheckControls();
