$('runProjectCheck')?.addEventListener('click',async()=>{
 const button=$('runProjectCheck'),cancel=$('cancelProjectCheck'),status=$('projectCheckStatus'),output=$('projectCheckOutput');
 const action=projectActionSelect?.value;
 if(!action){toast('Nejdřív vyber přednastavenou kontrolu.');return}
 try{
  if(!state.projectFolder)await chooseFolder();
  if(!state.projectFolder)return;
  button.disabled=true;if(cancel)cancel.disabled=false;
  if(status)status.textContent='KONTROLA BĚŽÍ';
  if(output)output.textContent='Spouštím bezpečně přednastavenou kontrolu…';
  const result=await window.aurora.runProjectCheck(action);
  if(result?.cancelled){if(status)status.textContent='ZRUŠENO';if(output)output.textContent=[result.note||'Kontrola byla zrušena.',`Doba: ${formatDuration(result.durationMs||0)}`].join('\n');toast('Projektová kontrola byla zrušena.');return}
  const heading=result.ok?'ÚSPĚŠNĚ DOKONČENO':result.cancelled?'ZRUŠENO':result.timedOut?'ČASOVÝ LIMIT':'KONTROLA SELHALA';
  const content=[heading,result.label||action,`Exit code: ${result.exitCode??'—'} · Doba: ${formatDuration(result.durationMs||0)}${result.outputTruncated?' · výstup zkrácen':''}`,'',result.stdout||'',result.stderr?`STDERR:\n${result.stderr}`:'',result.note||''].filter(Boolean).join('\n');
  if(status)status.textContent=result.ok?'HOTOVO':result.cancelled?'ZRUŠENO':'CHYBA';
  if(output)output.textContent=content;
  if(result.ok)toast('Projektová kontrola dokončena.');else toast('Projektová kontrola: '+(result.timedOut?'časový limit':result.cancelled?'zrušeno':'chyba'));
 }catch(error){if(status)status.textContent='CHYBA';if(output)output.textContent=error.message;toast('Projektová kontrola: '+error.message)}
 finally{button.disabled=false;if(cancel)cancel.disabled=true}
});
