function renderProposalReview(host, proposalId, files, options={}){
 const batch=options.batch===true;
 const loaded=new Set();
 host.innerHTML=`<div class="proposal-review-head"><b>ČEKÁ NA TVÉ SCHVÁLENÍ · ${files.length} ${files.length===1?'SOUBOR':'SOUBORŮ'}</b><p>${esc(options.summary||'Před zápisem zkontroluj celý obsah každého souboru. Zápis je vypnutý, dokud nenačteš úplný náhled všech položek.')}</p></div>${files.map((file,index)=>`<details class="agent-proposal-file proposal-review-file" ${index===0?'open':''}><summary>${esc(file.path)} · ${file.exists?'upravit a zálohovat':'nový soubor'}</summary><p class="muted">Zobrazený text je pouze úvodní výřez. Před schválením je nutné načíst celý původní i navržený obsah.</p><button type="button" class="secondary" data-review-load="${index}">Načíst úplný obsah souboru</button><div class="proposal-review-content"><b>Původní obsah</b><pre data-review-old="${index}">${esc(file.oldContent||'(Nový soubor — původní obsah neexistuje)')}</pre><b>Navržený obsah</b><pre data-review-new="${index}">${esc(file.newContent||'')}</pre></div><small data-review-status="${index}">Úplný náhled zatím nebyl načten.</small></details>`).join('')}${options.tests?.length?`<div class="proposal-review-tests"><b>Navržené kontroly</b><ul>${options.tests.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></div>`:''}<div class="batch-edit-actions"><button type="button" class="primary" data-review-approve disabled>Schválit a zapsat (${loaded.size}/${files.length} úplných náhledů)</button><button type="button" class="secondary" data-review-cancel>Zrušit návrh</button></div><small class="muted" data-review-note>Nejdřív načti a projdi celý obsah všech souborů.</small>`;
 const approve=host.querySelector('[data-review-approve]');
 const updateApproval=()=>{approve.disabled=loaded.size!==files.length;approve.textContent=loaded.size===files.length?'Schválit a zapsat celý návrh':`Schválit a zapsat (${loaded.size}/${files.length} úplných náhledů)`;host.querySelector('[data-review-note]').textContent=approve.disabled?'Nejdřív načti a projdi celý obsah všech souborů.':'Všechny úplné obsahy jsou načtené. Ještě zkontroluj rozdíly a pak můžeš návrh schválit.'};
 host.querySelectorAll('[data-review-load]').forEach(button=>button.addEventListener('click',async()=>{
  const index=Number(button.dataset.reviewLoad);if(loaded.has(index))return;
  button.disabled=true;button.textContent='Načítám celý soubor…';
  try{
   const payload={id:proposalId};if(batch)payload.index=index;
   const full=await window.aurora.readProposalPreviewFile(payload);
   const oldNode=host.querySelector(`[data-review-old="${index}"]`),newNode=host.querySelector(`[data-review-new="${index}"]`),status=host.querySelector(`[data-review-status="${index}"]`);
   oldNode.textContent=full.exists?full.oldContent:'(Nový soubor — původní obsah neexistuje)';newNode.textContent=full.newContent;
   status.textContent=`Úplný obsah načten · ${(full.bytes/1024).toLocaleString('cs-CZ',{maximumFractionDigits:1})} kB. Původní soubor ${full.exists?'byl ověřen':'neexistuje'}.`;
   loaded.add(index);button.textContent='Úplný obsah načten';button.disabled=true;updateApproval();
  }catch(error){button.disabled=false;button.textContent='Zkusit načíst znovu';toast(`Náhled ${files[index]?.path||''}: ${error.message}`)}
 }));
 approve.addEventListener('click',async()=>{
  if(approve.disabled||loaded.size!==files.length)return;
  if(!confirm(options.confirmText||`Opravdu schválit a zapsat ${files.length} ${files.length===1?'soubor':'souborů'} do vybraného projektu?`))return;
  approve.disabled=true;approve.textContent='Zapisuji schválené změny…';
  try{await options.onApprove?.();}
  catch(error){toast('Zápis odmítnut: '+error.message);updateApproval()}
 });
 host.querySelector('[data-review-cancel]').addEventListener('click',async()=>{
  const cancel=host.querySelector('[data-review-cancel]');cancel.disabled=true;
  try{await options.onCancel?.();}
  catch(error){cancel.disabled=false;toast('Zrušení návrhu: '+error.message)}
 });
 updateApproval();
}

$('previewEdit').onclick=async()=>{
 try{
  if(!state.projectFolder){toast('Nejdřív vyber projektovou složku.');return}
  const path=$('editPath').value.trim(),content=$('editContent').value;
  if(!path||!content){toast('Vyplň cestu i nový obsah.');return}
  const proposal=await window.aurora.prepareEdit({path,content});
  renderProposalReview($('editPreview'),proposal.id,[{path:proposal.path,exists:proposal.exists,oldContent:proposal.oldContent||'',newContent:proposal.newContent}],{
   batch:false,summary:'Zkontroluj celý původní i nový obsah. Zápis je povolen až po načtení úplného náhledu.',
   confirmText:`Opravdu zapsat ${proposal.path}? Existující soubor bude před změnou zálohován.`,
   onApprove:async()=>{const result=await window.aurora.approveEdit(proposal.id);$('editPreview').innerHTML=`<b>Zapsáno: ${esc(result.path)}</b><p>Záloha: ${esc(result.backup||'nový soubor — nebyla potřeba')}.</p>${result.backup?'<button class="secondary" id="rollbackEditNow">Vrátit zálohu</button>':''}`;if(result.backup)$('rollbackEditNow').onclick=async()=>{if(!confirm('Vrátit původní obsah souboru ze zálohy?'))return;try{const r=await window.aurora.rollback(result.backup);$('editPreview').textContent='Obnoveno: '+r.restored;toast('Původní soubor obnoven.')}catch(e){toast('Obnova selhala: '+e.message)}};toast('Změna byla schválena a zapsána.')},
   onCancel:async()=>{const outcome=await window.aurora.cancelEdit(proposal.id);if(outcome?.busy)throw new Error('Zápis už probíhá; návrh nelze zrušit. Počkej na výsledek.');if(!outcome?.cancelled)throw new Error('Návrh už byl zpracován nebo vypršel.');$('editPreview').textContent='Návrh zrušen. Soubor nebyl změněn.'}
  });
 }catch(e){toast('Návrh nelze připravit: '+e.message)}
};
$('exportWorkspace').onclick=async()=>{try{persistConversationDraft(true);const snapshot=window.AuroraWorkspacePersistence?.prepareWorkspace?.({model:state.model,preferences:state.preferences,conversations:state.conversations,activeConversationId:state.activeConversationId,folder:state.folder,projectFolder:state.projectFolder,performanceProfile:state.performanceProfile,autoRoute:state.autoRoute,provider:state.provider,agentConfig:state.agentConfig,agentComplexity:state.agentComplexity},{maxSerializedChars:8_000_000,contentBudget:6_000_000,maxMessages:4000,maxConversations:100,perConversationMessages:200,perMessageChars:50000});const result=await window.aurora.exportWorkspace(snapshot?.payload||{model:state.model,preferences:state.preferences,conversations:state.conversations});if(result.cancelled)return;$('workspaceBackupStatus').textContent=`Záloha uložena: ${result.path} · ${result.conversations} konverzací`;toast(result.trimmed?'Záloha uložena, ale část historie byla zkrácena kvůli limitu velikosti. Podrobnosti jsou uvedeny v hlášení exportu.':'Záloha Aurory byla exportována.')}catch(e){toast('Export zálohy selhal: '+e.message)}};
$('importWorkspace').onclick=async()=>{
 if(guardConversationSwitch())return;
 state.workspaceBusy=true;
 try{
  const incoming=await window.aurora.importWorkspace();
  if(incoming.cancelled)return;
  if(!Array.isArray(incoming.conversations))throw new Error('Záloha neobsahuje platný seznam konverzací.');
  if(!confirm(`Importovat ${incoming.conversations.length} konverzací? Existující historie zůstane zachována a duplicitní ID budou sloučena.`))return;
  const hadActiveConversation=!!state.activeConversationId;
  const known=new Set(state.conversations.map(c=>c.id));
  const importedIdMap=new Map();
  for(const source of incoming.conversations){
   if(!source||typeof source!=='object')continue;
   const c={...source,messages:Array.isArray(source.messages)?source.messages:[]};
   const originalId=String(c.id||'');
   if(!c.id||known.has(c.id)){c.id=crypto.randomUUID();c.title=(c.title||'Konverzace')+' (import)'}
   known.add(c.id);
   if(originalId)importedIdMap.set(originalId,c.id);
   state.conversations.push(c);
  }
  state.conversations.sort((a,b)=>(b.updatedAt||0)-(a.updatedAt||0));
  state.conversations=state.conversations.slice(0,500);
  if(incoming.model&&state.models.some(m=>m.name===incoming.model))state.model=incoming.model;
  if(['ollama','openai','anthropic','gemini'].includes(incoming.provider))state.provider=incoming.provider;
  if(['adaptive','quick','balanced','deep','extra','manual'].includes(incoming.performanceProfile))state.performanceProfile=incoming.performanceProfile;
  if(typeof incoming.autoRoute==='boolean')state.autoRoute=incoming.autoRoute;
  if(incoming.agentConfig&&window.AuroraAgentConfig?.normalizeAgentConfig)state.agentConfig=window.AuroraAgentConfig.normalizeAgentConfig(incoming.agentConfig);
  state.agentComplexity=incoming.agentComplexity==='advanced'?'advanced':'simple';
  if(incoming.folderSelected){$('scopePath').textContent='Vyber složku znovu pro nové oprávnění';state.folder=null}
  if(incoming.projectFolderSelected){$('projectPath').textContent='Vyber složku znovu pro nové oprávnění';state.projectFolder=null}
  if($('providerSelect'))$('providerSelect').value=state.provider;
  if($('autoRoute'))$('autoRoute').checked=state.autoRoute;
  if($('agentComplexity'))$('agentComplexity').value=state.agentComplexity;
  const prefs=incoming.preferences||{};
  state.preferences={...state.preferences,
   temperature:clampSetting(prefs.temperature,0,2,state.preferences.temperature),
   top_p:clampSetting(prefs.top_p,0.05,1,state.preferences.top_p),
   top_k:Math.round(clampSetting(prefs.top_k,1,200,state.preferences.top_k)),
   repeat_penalty:clampSetting(prefs.repeat_penalty,0.5,2,state.preferences.repeat_penalty),
   seed:prefs.seed===null||prefs.seed===''?null:Math.round(clampSetting(prefs.seed,0,2147483647,0)),
   stop_sequences:typeof prefs.stop_sequences==='string'?prefs.stop_sequences.slice(0,300):state.preferences.stop_sequences,
   system_prompt:typeof prefs.system_prompt==='string'?prefs.system_prompt.slice(0,6000):state.preferences.system_prompt,
   ...(window.AuroraUserProfile?.normalizeUserProfile?.(prefs)||{}),
   response_language:['auto','cs','en'].includes(prefs.response_language)?prefs.response_language:state.preferences.response_language,
   keep_alive:['0','1m','5m','10m','30m','1h'].includes(String(prefs.keep_alive))?String(prefs.keep_alive):state.preferences.keep_alive,
   stream_responses:prefs.stream_responses!==false,
   num_ctx:clampSetting(prefs.num_ctx,512,131072,state.preferences.num_ctx),
   num_predict:clampSetting(prefs.num_predict,1,32768,state.preferences.num_predict),
   num_thread:clampSetting(prefs.num_thread,1,128,state.preferences.num_thread)
  };
  // If the current workspace has no active conversation, open the backed-up active chat when it survived ID remapping.
  if(!hadActiveConversation&&incoming.activeConversationId){
   const importedActiveId=importedIdMap.get(incoming.activeConversationId);
   if(importedActiveId&&state.conversations.some(c=>c.id===importedActiveId))state.activeConversationId=importedActiveId;
  }
  const boundedWorkspace=window.AuroraWorkspacePersistence?.prepareWorkspace?.({conversations:state.conversations,activeConversationId:state.activeConversationId});
  if(boundedWorkspace){state.conversations=boundedWorkspace.payload.conversations;state.activeConversationId=boundedWorkspace.payload.activeConversationId;}
  const active=state.conversations.find(c=>c.id===state.activeConversationId);
  if(active){
   const recovery=recoverInterruptedMessages(active.messages||[]);
   state.messages=recovery.messages;
   if(active.storageTrimmed){state.messages.unshift({role:'system',content:'Upozornění: záloha neobsahuje celou starší historii této konverzace.'});active.storageTrimmed=false}
   $('viewTitle').textContent=active.title||'Konverzace';
  }
  $('temperature').value=state.preferences.temperature;
  $('temperatureValue').textContent=state.preferences.temperature.toLocaleString('cs-CZ',{minimumFractionDigits:1,maximumFractionDigits:1});
  $('contextSize').value=String(state.preferences.num_ctx);
  $('maxTokens').value=String(state.preferences.num_predict);
  $('threadCount').value=String(state.preferences.num_thread);
  if($('performanceProfile'))$('performanceProfile').value=state.performanceProfile;
  syncGenerationPreferenceControls();fillAgentModels();updateProviderVisual();persist();renderHistory();renderMessages();updateModelLabel();
  $('workspaceBackupStatus').textContent=`Import dokončen · celkem ${state.conversations.length} konverzací`;
  toast('Záloha byla importována.');
 }catch(e){toast('Import zálohy selhal: '+e.message)}finally{state.workspaceBusy=false}
};
