async function refreshOpenAIStatus(requestedProtocol=null){try{const protocol=requestedProtocol||$('remoteProtocol')?.value||null;const s=await window.aurora.openAIStatus(protocol||undefined);$('openAIStatus').textContent=s.configured?`Klíč uložen · ${s.label} · model ${s.model} · šifrování ${s.encryptionAvailable?'dostupné':'nedostupné'}`:`API klíč pro ${s.label||s.protocol} není uložen · systémové šifrování ${s.encryptionAvailable?'dostupné':'nedostupné'}`;$('openAIModel').value=s.model||$('openAIModel').value;if($('openAILabel'))$('openAILabel').value=s.label||s.protocol||'OpenAI';if($('openAIEndpoint'))$('openAIEndpoint').value=s.baseUrl||'https://api.openai.com/v1';if($('remoteProtocol'))$('remoteProtocol').value=s.protocol||requestedProtocol||'openai'}catch(e){$('openAIStatus').textContent='Stav API se nepodařilo načíst: '+e.message}}
$('saveOpenAI')?.addEventListener('click',async()=>{const btn=$('saveOpenAI');btn.disabled=true;try{const protocol=$('remoteProtocol')?.value||'openai';const r=await window.aurora.saveOpenAI({protocol,apiKey:$('openAIKey').value,model:$('openAIModel').value,label:$('openAILabel').value,baseUrl:$('openAIEndpoint').value});$('openAIKey').value='';$('openAIStatus').textContent=`${r.configured?'Klíč bezpečně uložen':'Nastavení uloženo bez změny klíče'} · ${r.label} · model ${r.model}`;toast('API nastavení uloženo pro '+r.protocol+'.');}catch(e){$('openAIStatus').textContent=e.message;toast('Uložení API nastavení selhalo.')}finally{btn.disabled=false}});
