$('clearOpenAI')?.addEventListener('click',async()=>{const protocol=$('remoteProtocol')?.value||'openai';if(!confirm(`Odebrat uložený API klíč pro ${protocol}?`))return;try{await window.aurora.clearOpenAI(protocol);$('openAIKey').value='';await refreshOpenAIStatus(protocol);toast('API klíč pro '+protocol+' byl odebrán.')}catch(e){$('openAIStatus').textContent=e.message}});
