function syncGenerationPreferenceControls(){
 const p=state.preferences;
 const set=(id,value)=>{const el=$(id);if(el&&document.activeElement!==el)el.value=value==null?'':String(value)};
 set('topP',p.top_p);set('topK',p.top_k);set('repeatPenalty',p.repeat_penalty);set('randomSeed',p.seed);set('systemPrompt',p.system_prompt);set('stopSequences',p.stop_sequences);set('keepAlive',p.keep_alive);set('defaultPerformanceProfile',state.performanceProfile);
 set('generationLanguage',p.response_language||'auto');
 set('settingsTemperature',p.temperature);set('settingsTopP',p.top_p);set('settingsTopK',p.top_k);set('settingsRepeatPenalty',p.repeat_penalty);set('settingsSeed',p.seed);set('settingsContextSize',p.num_ctx);set('settingsMaxTokens',p.num_predict);set('settingsThreadCount',p.num_thread);
 set('temperature',p.temperature);set('contextSize',p.num_ctx);set('maxTokens',p.num_predict);set('threadCount',p.num_thread);
 const stream=$('streamResponses');if(stream)stream.checked=p.stream_responses!==false;
 const output=(id,value,locale='cs-CZ',max=2)=>{const el=$(id);if(el)el.textContent=Number(value).toLocaleString(locale,{maximumFractionDigits:max})};
 output('topPValue',p.top_p);output('repeatPenaltyValue',p.repeat_penalty);output('settingsTemperatureValue',p.temperature);output('settingsTopPValue',p.top_p);output('settingsRepeatPenaltyValue',p.repeat_penalty);
 const tv=$('temperatureValue');if(tv)tv.textContent=Number(p.temperature).toLocaleString('cs-CZ',{minimumFractionDigits:1,maximumFractionDigits:1});
}
