function saveGenerationSettings(){
 const p=state.preferences;
 p.temperature=clampSetting($('settingsTemperature')?.value??$('temperature')?.value,0,2,0.7);
 p.top_p=clampSetting($('settingsTopP')?.value??$('topP')?.value,0.05,1,0.9);
 p.top_k=Math.round(clampSetting($('settingsTopK')?.value??$('topK')?.value,1,200,40));
 p.repeat_penalty=clampSetting($('settingsRepeatPenalty')?.value??$('repeatPenalty')?.value,0.5,2,1.1);
 const seedValue=$('settingsSeed')?.value??$('randomSeed')?.value;
 p.seed=seedValue===''||seedValue==null?null:Math.round(clampSetting(seedValue,0,2147483647,0));
 p.num_ctx=Math.round(clampSetting($('settingsContextSize')?.value??$('contextSize')?.value,512,131072,4096));
 p.num_predict=Math.round(clampSetting($('settingsMaxTokens')?.value??$('maxTokens')?.value,1,32768,1024));
 p.num_thread=Math.round(clampSetting($('settingsThreadCount')?.value??$('threadCount')?.value,1,128,4));
 p.system_prompt=String($('systemPrompt')?.value||'').slice(0,6000);
 p.stop_sequences=String($('stopSequences')?.value||'').slice(0,300);
 p.keep_alive=['0','1m','5m','10m','30m','1h'].includes(String($('keepAlive')?.value))?String($('keepAlive').value):'10m';
 p.stream_responses=$('streamResponses')?.checked!==false;
 p.response_language=['auto','cs','en'].includes($('generationLanguage')?.value)?$('generationLanguage').value:'auto';
 const profile=$('defaultPerformanceProfile')?.value;if(['adaptive','quick','balanced','deep','extra','manual'].includes(profile))state.performanceProfile=profile;
 if($('performanceProfile'))$('performanceProfile').value=state.performanceProfile;
 persist();syncGenerationPreferenceControls();updatePerformanceHint($('prompt')?.value||'');toast('Nastavení generování uloženo.');
}

