// The settings screen uses compact category tabs; one category is shown at a time to avoid an overwhelming wall of controls.
function setSettingsCategory(category){
 const grid=document.querySelector('.settings-grid');if(!grid)return;
 const known=['appearance','personalization','generation','sound','providers','data','safety','all'];const selected=known.includes(category)?category:'appearance';grid.dataset.settingsFilter=selected;
 document.querySelectorAll('.settings-tab[data-settings-filter]').forEach(tab=>{const active=tab.dataset.settingsFilter===selected;tab.classList.toggle('active',active);tab.setAttribute('aria-selected',String(active));});
 grid.querySelectorAll('[data-settings-category]').forEach(card=>{card.hidden=selected!=='all'&&card.dataset.settingsCategory!==selected;});syncNavigation(state.view,NAV_GROUP_FOR_VIEW[state.view]||null);
}
