// Advanced model controls are mirrors of the chat controls; both surfaces update the same validated state.
for(const id of ['settingsTemperature','settingsTopP','settingsTopK','settingsRepeatPenalty','settingsSeed','settingsContextSize','settingsMaxTokens','settingsThreadCount']){
 const el=$(id);if(!el)continue;
 const eventType=el.type==='range'||el.type==='number'?'input':'change';
 el.addEventListener(eventType,()=>{state.performanceProfile='manual';if($('defaultPerformanceProfile'))$('defaultPerformanceProfile').value='manual';if($('performanceProfile'))$('performanceProfile').value='manual';saveGenerationSettings();});
 if(eventType==='input')el.addEventListener('change',()=>{state.performanceProfile='manual';if($('defaultPerformanceProfile'))$('defaultPerformanceProfile').value='manual';if($('performanceProfile'))$('performanceProfile').value='manual';saveGenerationSettings();});
}

function activateManualPerformance(){state.performanceProfile='manual';if($('performanceProfile'))$('performanceProfile').value='manual';updatePerformanceHint($('prompt').value)}
$('temperature').addEventListener('input',()=>{state.preferences.temperature=clampSetting($('temperature').value,0,2,0.7);$('temperatureValue').textContent=state.preferences.temperature.toLocaleString('cs-CZ',{minimumFractionDigits:1,maximumFractionDigits:1});activateManualPerformance();persist();syncGenerationPreferenceControls()});
