$('maxTokens').addEventListener('change',()=>{state.preferences.num_predict=Math.round(clampSetting($('maxTokens').value,1,32768,1024));activateManualPerformance();persist();syncGenerationPreferenceControls()});$('threadCount').addEventListener('change',()=>{state.preferences.num_thread=Math.round(clampSetting($('threadCount').value,1,128,4));activateManualPerformance();persist();syncGenerationPreferenceControls()});
