async function chatWithStream(payload,onChunk){const requestId=crypto.randomUUID();state.activeRequestId=requestId;const off=window.aurora.onChatChunk(chunk=>{if(chunk.requestId===requestId)onChunk?.(chunk.text)});try{return await window.aurora.chat({...payload,requestId})}finally{off?.();if(state.activeRequestId===requestId)state.activeRequestId=null}}
