  const cfg=state.agentConfig[role],provider=$(`${role}Provider`),local=$(`${role}LocalModel`),remote=$(`${role}RemoteModel`),localWrap=$(`${role}LocalWrap`),remoteWrap=$(`${role}RemoteWrap`),help=$(`${role}ProviderHelp`);
