function formatBytes(bytes){if(!Number.isFinite(Number(bytes))||Number(bytes)<0)return '—';const n=Number(bytes);if(n===0)return '0 B';const units=['B','KB','MB','GB','TB'];const i=Math.min(units.length-1,Math.floor(Math.log(n)/Math.log(1024)));return (n/1024**i).toFixed(i>=3?2:0)+' '+units[i]}
const TELEMETRY_KEY='aurora.performance.telemetry.v1';
function readTelemetry(){try{const value=JSON.parse(localStorage.getItem(TELEMETRY_KEY)||'[]');return Array.isArray(value)?value.slice(-40):[]}catch{return []}}
function saveTelemetry(sample){const api=window.AuroraPerformanceTelemetry;if(!api)return;const next=api.appendSample(readTelemetry(),sample);try{localStorage.setItem(TELEMETRY_KEY,JSON.stringify(next))}catch{}renderTelemetry()}
function formatDuration(ms){if(!Number.isFinite(ms))return '—';return ms>=1000?(ms/1000).toLocaleString('cs-CZ',{maximumFractionDigits:1})+' s':Math.round(ms)+' ms'}
function renderTelemetry(){const api=window.AuroraPerformanceTelemetry;if(!api)return;const samples=readTelemetry();const summary=api.summarize(samples);const set=(id,value)=>{const el=$(id);if(el)el.textContent=value};set('telemetryCount',String(summary.count));set('telemetryAverage',formatDuration(summary.averageMs));set('telemetryFirst',formatDuration(summary.averageFirstTokenMs));set('telemetryChars',Number.isFinite(summary.averageCharsPerSecond)?summary.averageCharsPerSecond.toLocaleString('cs-CZ',{maximumFractionDigits:1})+' znaků/s':'—');const host=$('telemetryRecent');if(!host)return;const completed=samples.filter(x=>x.completed&&Number.isFinite(x.totalMs)).slice(-8).reverse();host.innerHTML=completed.length?completed.map(x=>`<article class="runtime-model"><div><b>${esc(x.model)} · ${esc(x.profile)}</b><small>${new Date(x.at).toLocaleString('cs-CZ')} · ${esc(x.provider)} · ${Number(x.outputChars)||0} znaků${x.omittedMessages?` · vynecháno ${x.omittedMessages} zpráv`:''}</small></div><div class="runtime-memory"><b>${formatDuration(x.totalMs)}</b><small>První výstup ${formatDuration(x.firstTokenMs)} · ${Number.isFinite(x.charsPerSecond)?x.charsPerSecond+' zn/s':'—'}</small></div></article>`).join(''):'<div class="empty-state">Po dokončení chatu se zde zobrazí první měření.</div>'}
$('clearTelemetry')?.addEventListener('click',()=>{localStorage.removeItem(TELEMETRY_KEY);renderTelemetry();toast('Historie měření byla vymazána.')});
async function refreshRuntime(){const button=$('refreshRuntime');if(button){button.disabled=true;button.textContent='Načítám…'}try{const r=await window.aurora.runningModels();state.runtime=r;if(!$('performanceView'))return;$('runtimeUpdated').textContent='Kontrola: '+new Date(r.checkedAt||Date.now()).toLocaleString('cs-CZ');$('runtimeConnection').textContent=r.ok?'Ollama dostupná · '+(r.system?.cpu||'CPU neznámé'):'Ollama není dostupná: '+(r.error||'neznámá chyba');$('runtimeFreeRam').textContent=(r.system?.freeRamGB??'—')+' GB';$('runtimeTotalRam').textContent='Celkem '+(r.system?.ramGB??'—')+' GB · '+(r.system?.cores??'—')+' CPU vláken';$('runtimeInstalledCount').textContent=String(r.available?.length||0);$('runtimeLoadedCount').textContent=String(r.running?.length||0);$('runtimeLoadedSize').textContent=formatBytes((r.running||[]).reduce((sum,m)=>sum+(Number(m.size)||0),0));const list=$('runtimeModelList');if(!r.ok)list.innerHTML='<div class="empty-state">Spusť Ollama a zkus kontrolu znovu.</div>';else if(!r.running?.length)list.innerHTML='<div class="empty-state">Žádný model není právě načtený. Po první zprávě se může objevit zde.</div>';else list.innerHTML=r.running.map(m=>`<article class="runtime-model"><div><b>${esc(m.name||m.model||'Neznámý model')}</b><small>${esc(m.details?.parameter_size||'Velikost parametrů neznámá')} · ${esc(m.details?.quantization_level||'kvantizace neznámá')} · kontext ${Number(m.context_length)||'—'}</small></div><div class="runtime-memory"><b>${formatBytes(m.size)}</b><small>VRAM ${formatBytes(m.size_vram)}</small></div></article>`).join('')}catch(e){if($('runtimeConnection'))$('runtimeConnection').textContent='Chyba: '+e.message}finally{if(button){button.disabled=false;button.textContent='↻ Obnovit runtime'}}}
async function refreshCompatibility({quiet=false}={}){
 const button=$('refreshCompatibility');const grid=$('compatibilityGrid');const summary=$('compatibilitySummary');const runtime=$('compatibilityRuntime');
 if(button){button.disabled=true;button.textContent='Kontroluji…'}
 if(grid)grid.innerHTML='<div class="empty-state">Zjišťuji verze dostupných nástrojů…</div>';
 try{
  const result=await window.aurora.compatibility();
  const tools=Array.isArray(result.tools)?result.tools:[];
  const labels={available:'DOSTUPNÉ',outdated:'AKTUALIZOVAT',missing:'NENALEZENO',unverified:'NEOVĚŘENO'};
  if(runtime){const desktop=result.desktop||{};const platformLabel=({win32:'Windows',darwin:'macOS',linux:'Linux'})[result.platform]||result.platform;runtime.replaceChildren();for(const [label,value] of [['OS',platformLabel],['Architektura',result.arch],['Electron',desktop.electron],['Chromium',desktop.chromium],['Node uvnitř Aurory',desktop.embeddedNode]]){const span=document.createElement('span');span.textContent=label;const strong=document.createElement('b');strong.textContent=value||'—';runtime.append(span,strong)}}
  if(summary){const counts=result.summary||{};summary.textContent=`${counts.available||0} dostupných · ${counts.outdated||0} k aktualizaci · ${counts.missing||0} nenalezených · ${counts.unverified||0} neověřených · ${new Date(result.checkedAt||Date.now()).toLocaleTimeString('cs-CZ')}`}
  if(grid){grid.replaceChildren();for(const tool of tools){const card=document.createElement('article');card.className=`compatibility-item ${['available','outdated','missing','unverified'].includes(tool.status)?tool.status:'unverified'}`;const head=document.createElement('div');head.className='compatibility-item-head';const name=document.createElement('b');name.textContent=tool.label||tool.id;const stateLabel=document.createElement('span');stateLabel.className='compatibility-state';stateLabel.textContent=labels[tool.status]||'NEOVĚŘENO';head.append(name,stateLabel);const purpose=document.createElement('p');purpose.textContent=tool.purpose||'';const detail=document.createElement('small');detail.textContent=tool.version|| (tool.path?'Cesta nalezena':'Spustitelný soubor nebyl nalezen');detail.title=tool.path||'';const note=document.createElement('small');note.className='compatibility-note';note.textContent=tool.note||tool.requiredFor||'';card.append(head,purpose,detail,note);grid.appendChild(card)}}
  if(!quiet)toast('Kompatibilita nástrojů byla ověřena.');
  state.hostCompatibility=result;
 }catch(error){if(grid){const message=document.createElement('div');message.className='empty-state';message.textContent='Kontrola kompatibility selhala: '+String(error.message||error);grid.replaceChildren(message)}if(summary)summary.textContent='Kompatibilitu se nepodařilo načíst.';if(!quiet)toast('Kontrola kompatibility selhala: '+String(error.message||error).slice(0,180))}
 finally{if(button){button.disabled=false;button.textContent='↻ Zkontrolovat znovu'}}
}
