async function refreshComfyStatus(){
 const dot=$('comfyStatusDot'),title=$('comfyStatusTitle'),detail=$('comfyStatusText');
 try{const status=await window.aurora.comfyStatus();imageWorkflowLoaded=!!status.workflowLoaded;dot.classList.toggle('online',!!status.available&&imageWorkflowLoaded);title.textContent=!status.available?'ComfyUI není spuštěné':imageWorkflowLoaded?'ComfyUI a workflow jsou připravené':'ComfyUI běží · chybí workflow';detail.textContent=!status.available?status.message:(imageWorkflowLoaded?`${status.workflowName||'Workflow načten'} · ${status.device||status.message}`:(status.workflowError||'Vyber API workflow jen jednou; Aurora si ho uloží.'));$('imageWorkflowLabel').textContent=imageWorkflowLoaded?(status.workflowName||'Workflow načten'):'Workflow není vybraný';$('generateImage').disabled=!status.available||!imageWorkflowLoaded}
 catch(e){dot.classList.remove('online');title.textContent='ComfyUI není dostupné';detail.textContent=e.message;$('generateImage').disabled=true}
}
let imageWorkflowLoaded=false;
const IMAGE_HISTORY_KEY='aurora.imageHistory.v1';
function loadImageHistory(){try{return JSON.parse(localStorage.getItem(IMAGE_HISTORY_KEY)||'[]').filter(x=>x&&typeof x.url==='string'&&x.url.startsWith('http://127.0.0.1:8188/')).slice(0,24)}catch{return []}}
function renderImageHistory(){const host=$('imageHistory');if(!host)return;const items=loadImageHistory();host.innerHTML='';if(!items.length){host.innerHTML='<div class="muted">Zatím žádná historie. Po úspěšném generování se zde objeví lokální náhledy.</div>';return}for(const item of items){const card=document.createElement('button');card.className='image-history-item';card.type='button';const img=document.createElement('img');img.src=item.url;img.alt='Dříve vygenerovaný obrázek';img.loading='lazy';const caption=document.createElement('small');caption.textContent=(item.prompt||'Bez promptu').slice(0,90);card.append(img,caption);card.addEventListener('click',()=>{const full=document.createElement('img');full.src=item.url;full.alt='Vygenerovaný obrázek';full.className='generated-image';$('imagePreview').replaceChildren(full);$('imageGenerationState').textContent='Historie';$('imageOutputList').textContent=new Date(item.at||Date.now()).toLocaleString('cs-CZ')});host.appendChild(card)}}
$('clearImageHistory').addEventListener('click',()=>{if(!confirm('Opravdu vymazat místní historii odkazů na obrázky? Samotné soubory v ComfyUI se nesmažou.'))return;localStorage.removeItem(IMAGE_HISTORY_KEY);renderImageHistory();toast('Historie Aurory vymazána. Soubory ComfyUI zůstávají.')});
$('checkComfy').addEventListener('click',refreshComfyStatus);
$('chooseImageWorkflow').addEventListener('click',async()=>{
 try{const result=await window.aurora.chooseImageWorkflow();if(result.cancelled)return;imageWorkflowLoaded=true;$('imageWorkflowLabel').textContent=`${result.name} · ${result.nodes} uzlů`;$('imageWorkflowLabel').title=result.name;toast('ComfyUI workflow načteno');await refreshComfyStatus()}
 catch(e){imageWorkflowLoaded=false;$('imageWorkflowLabel').textContent='Workflow se nepodařilo načíst';toast(e.message);await refreshComfyStatus()}
});
$('generateImage').addEventListener('click',async()=>{
 const prompt=$('imagePrompt').value.trim();if(prompt.length<3){toast('Nejdřív napiš popis obrázku.');return}
 const button=$('generateImage');button.disabled=true;button.textContent='Generuji…';$('imageGenerationState').textContent='Generuji';$('imagePreview').innerHTML='<div class="image-preview-placeholder"><div class="spinner"></div><b>ComfyUI vytváří obrázek</b><small>Generování může chvíli trvat podle modelu a rozlišení.</small></div>';
 try{
  const result=await window.aurora.generateImage({prompt,negative:$('imageNegative').value});
  $('imageGenerationState').textContent=`Hotovo · ${(result.elapsedMs/1000).toFixed(1)} s`;
  $('imagePreview').innerHTML='';
  for(const [i,item] of result.outputs.entries()){
   const img=document.createElement('img');img.src=item.url;img.alt=`Vygenerovaný obrázek ${i+1}`;img.loading='lazy';img.className='generated-image';img.addEventListener('error',()=>{img.alt='Výstup ComfyUI se nepodařilo načíst'});
   $('imagePreview').appendChild(img);
  }
  $('imageOutputList').innerHTML=`<span class="tag">Prompt ID: ${esc(result.promptId)}</span><span class="tag">${result.outputs.length} výstupů</span>`;
  try{const old=loadImageHistory();const entries=result.outputs.map(item=>({url:item.url,prompt,at:Date.now(),promptId:result.promptId}));localStorage.setItem(IMAGE_HISTORY_KEY,JSON.stringify([...entries,...old].slice(0,24)));renderImageHistory()}catch(e){console.warn('Image history unavailable',e)}
  toast('Generování obrázku dokončeno')
 }catch(e){$('imageGenerationState').textContent='Chyba';$('imagePreview').innerHTML=`<div class="image-preview-placeholder image-error"><span>!</span><b>Obrázek se nepodařilo vygenerovat</b><small>${esc(e.message)}</small></div>`;toast('Generování selhalo: '+e.message)}
 finally{button.textContent='✧ Generovat obrázek';await refreshComfyStatus()}
});

function closeGuide(){const modal=$('guideModal');if(!modal||modal.classList.contains('hidden'))return;modal.classList.add('is-closing');window.setTimeout(()=>{modal.classList.add('hidden');modal.classList.remove('is-closing')},160);$('helpGuideBtn')?.focus();}
function openGuide(){const modal=$('guideModal');if(!modal)return;modal.classList.remove('hidden','is-closing');$('closeGuide')?.focus();window.AuroraUI?.playSound?.('open');}
$('helpGuideBtn')?.addEventListener('click',openGuide);$('closeGuide')?.addEventListener('click',closeGuide);document.querySelectorAll('[data-close-guide="true"]').forEach(el=>el.addEventListener('click',closeGuide));document.querySelectorAll('[data-guide-view]').forEach(button=>button.addEventListener('click',()=>{const view=button.dataset.guideView;closeGuide();setView(view,{navGroup:NAV_GROUP_FOR_VIEW[view]||null});}));document.querySelectorAll('[data-guide-category]').forEach(button=>button.addEventListener('click',()=>{closeGuide();setView('settings',{settingsCategory:button.dataset.guideCategory});}));document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('guideModal')?.classList.contains('hidden'))closeGuide();});

async function refreshLocalMemoryUI(){
 const enabled=$('memoryEnabled'),modelInput=$('memoryEmbeddingModel'),status=$('memoryStatus'),host=$('localMemoryList');if(!enabled||!modelInput||!status||!host||!window.aurora.memoryStatus)return;
 try{
  const config=await window.aurora.memoryStatus();state.localMemoryEnabled=config.enabled===true;enabled.checked=state.localMemoryEnabled;if(document.activeElement!==modelInput)modelInput.value=config.embeddingModel||'nomic-embed-text';status.textContent=`${config.enabled?'Zapnuto':'Vypnuto'} · ${config.count||0} poznámek · pouze lokální Ollama · nezahrnuje se do zálohy chatu`;
  const items=await window.aurora.listMemory();host.replaceChildren();if(!items.length){const empty=document.createElement('p');empty.className='muted';empty.textContent='Zatím žádné uložené poznámky. Paměť se plní pouze záznamy, které uložíš ručně.';host.appendChild(empty);return}
  for(const item of items){const card=document.createElement('article');card.className='local-memory-entry';const title=document.createElement('h4');title.textContent=item.title||'Lokální poznámka';const content=document.createElement('p');content.textContent=item.text;const meta=document.createElement('small');meta.textContent=`${new Date(item.createdAt||Date.now()).toLocaleString()} · ${item.embeddingModel||config.embeddingModel}`;const remove=document.createElement('button');remove.type='button';remove.className='secondary';remove.textContent='Smazat';remove.addEventListener('click',async()=>{remove.disabled=true;try{await window.aurora.deleteMemory(item.id);await refreshLocalMemoryUI();toast('Lokální poznámka smazána.')}catch(error){toast('Poznámku se nepodařilo smazat: '+error.message)}finally{remove.disabled=false}});card.append(title,content,meta,remove);host.appendChild(card)}
 }catch(error){status.textContent='Lokální paměť není dostupná: '+String(error?.message||error).slice(0,180);host.replaceChildren();const note=document.createElement('p');note.className='muted';note.textContent='Zkontroluj stav profilu aplikace a lokální index paměti.';host.appendChild(note)}
}
$('memoryEnabled')?.addEventListener('change',async()=>{const toggle=$('memoryEnabled');toggle.disabled=true;try{const result=await window.aurora.setMemoryConfig({enabled:toggle.checked,embeddingModel:$('memoryEmbeddingModel').value.trim()||'nomic-embed-text'});state.localMemoryEnabled=result.enabled;state.memoryWarningShown=false;toast(result.enabled?'Lokální paměť zapnuta. Před prvním použitím ověř embedding model.':'Lokální paměť vypnuta. Uložené poznámky zůstávají do ručního smazání.');await refreshLocalMemoryUI()}catch(error){toggle.checked=state.localMemoryEnabled;toast('Nastavení paměti se nepodařilo uložit: '+error.message)}finally{toggle.disabled=false}});
$('checkMemoryModel')?.addEventListener('click',async()=>{const button=$('checkMemoryModel');button.disabled=true;const model=$('memoryEmbeddingModel').value.trim()||'nomic-embed-text';try{const cfg=await window.aurora.setMemoryConfig({enabled:$('memoryEnabled').checked,embeddingModel:model});state.localMemoryEnabled=cfg.enabled;const result=await window.aurora.checkMemoryModel();$('memoryStatus').textContent=`Model ${result.model} funguje · vektor ${result.dimensions} rozměrů · lokálně`;toast('Embedding model je připraven.')}catch(error){$('memoryStatus').textContent='Kontrola selhala: '+String(error.message||error).slice(0,220);toast('Embedding model se nepodařilo ověřit.')}finally{button.disabled=false;await refreshLocalMemoryUI()}});
$('refreshMemory')?.addEventListener('click',refreshLocalMemoryUI);
$('saveMemory')?.addEventListener('click',async()=>{const button=$('saveMemory'),text=$('memoryDraft').value.trim(),title=$('memoryTitle').value.trim();if(text.length<3){toast('Napiš nejdřív krátkou poznámku.');return}button.disabled=true;button.textContent='Ukládám lokálně…';try{const result=await window.aurora.addMemory({title,text});$('memoryDraft').value='';$('memoryTitle').value='';$('memoryStatus').textContent=`Poznámka bezpečně uložena lokálně · ${result.count} poznámek`;toast('Lokální poznámka uložena.');await refreshLocalMemoryUI()}catch(error){toast('Poznámku se nepodařilo uložit: '+error.message);$('memoryStatus').textContent=String(error.message||error).slice(0,220)}finally{button.disabled=false;button.textContent='Uložit lokální poznámku'}});
$('clearMemory')?.addEventListener('click',async()=>{if(!confirm('Opravdu trvale smazat všechny lokální poznámky Aurory? Tento krok nelze vrátit zpět.'))return;const button=$('clearMemory');button.disabled=true;try{await window.aurora.clearMemory();await refreshLocalMemoryUI();toast('Všechny lokální poznámky byly smazány.')}catch(error){toast('Paměť se nepodařilo vymazat: '+error.message)}finally{button.disabled=false}});
$('exportMemory')?.addEventListener('click',async()=>{const button=$('exportMemory');button.disabled=true;try{const result=await window.aurora.exportMemory();if(!result.cancelled)toast(`Exportováno ${result.count} lokálních poznámek do ${result.fileName}.`)}catch(error){toast('Export lokální paměti selhal: '+String(error.message||error).slice(0,180))}finally{button.disabled=false}});
$('importMemory')?.addEventListener('click',async()=>{const button=$('importMemory');button.disabled=true;try{const result=await window.aurora.importMemory();if(!result.cancelled){await refreshLocalMemoryUI();toast(`Importováno ${result.imported} poznámek · celkem ${result.count}. Paměť zůstává ${result.enabled?'zapnutá':'vypnutá'}.`)}}catch(error){toast('Import lokální paměti selhal: '+String(error.message||error).slice(0,220))}finally{button.disabled=false}});

async function refreshOllamaServiceButtons(){
 const start=$('ollamaStartBtn'),stop=$('ollamaStopBtn');if(!start||!stop)return;
 try{const r=await window.aurora.serviceStatus();const online=!!r.online;start.disabled=online;stop.disabled=!r.managed;start.textContent=online?'● Online':'▶ Start / instalovat';stop.title=r.managed?'Vypnout Ollama spuštěnou Aurorou':'Lze vypnout jen instanci spuštěnou Aurorou';}
 catch{start.disabled=false;stop.disabled=true;}
}
$('ollamaStartBtn')?.addEventListener('click',async()=>{
 const button=$('ollamaStartBtn');button.disabled=true;button.textContent='Spouštím…';
 try{
  let result;
  try{result=await window.aurora.startOllama()}
  catch(error){
   if(!String(error?.message||error).includes('[OLLAMA_NOT_INSTALLED]'))throw error;
   const accepted=confirm('Ollama není nainstalovaná. Chceš ji stáhnout a nainstalovat přes Windows Package Manager (winget)?');
   if(!accepted){toast('Instalace Ollama byla přeskočena.');return}
   button.textContent='Instaluji…';
   try{const installed=await window.aurora.installOllama();toast(installed.message||'Ollama byla nainstalována.');button.textContent='Spouštím…';result=await window.aurora.startOllama()}
   catch(installError){
    const message=String(installError?.message||installError);
    if(message.includes('[WINGET_NOT_AVAILABLE]')){await window.aurora.openOllama();toast('Winget není dostupný. Otevřela jsem oficiální stažení Ollama.')}
    else toast('Instalace Ollama selhala: '+message);
    return;
   }
  }
  toast(result?.message||'Ollama je připravená.');await refreshStatus({notify:true});await refreshOllamaServiceButtons();
 }catch(error){toast('Ollama se nepodařilo spustit: '+error.message)}
 finally{button.disabled=false;await refreshOllamaServiceButtons()}
});
$('ollamaStopBtn')?.addEventListener('click',async()=>{const button=$('ollamaStopBtn');button.disabled=true;try{const r=await window.aurora.stopOllama();toast(r.message||'Požadavek na vypnutí dokončen.');await refreshStatus();await refreshOllamaServiceButtons()}catch(error){toast('Ollama se nepodařilo vypnout: '+error.message)}finally{await refreshOllamaServiceButtons()}});
$('prepareImageEngine')?.addEventListener('click',async()=>{const button=$('prepareImageEngine'),note=$('imageSetupNote')?.querySelector('p');button.disabled=true;button.textContent='Připravuji…';if(note)note.textContent='Příprava může stáhnout několik GB. Nezavírej Auroru; průběh se zobrazuje zde.';const off=window.aurora.onImageSetupProgress?.(line=>{if(note)note.textContent=line; if($('imageGenerationState'))$('imageGenerationState').textContent='Příprava…'});try{const result=await window.aurora.prepareImageEngine();if(result.cancelled){if(note)note.textContent='Příprava byla zrušena. Nic dalšího se nestáhlo.';return}if(note)note.textContent='ComfyUI, Python, CPU backend, model a výchozí workflow jsou připravené. Obrazové generování může běžet pomaleji v CPU režimu.';toast('Obrazový engine je připraven.');await refreshComfyStatus();}catch(error){if(note)note.textContent='Příprava selhala: '+error.message;toast('Obrazový engine: '+error.message)}finally{off?.();button.disabled=false;button.textContent='Připravit generování obrázků';if($('imageGenerationState'))$('imageGenerationState').textContent='Připraveno'}});
window.addEventListener('DOMContentLoaded',async()=>{const modelDetail=$('modelDetail');if(modelDetail&&modelDetail.parentElement!==document.body)document.body.appendChild(modelDetail);restore();setMode(state.mode);syncEffortPicker();persist();syncGenerationPreferenceControls();syncPersonalizationControls();setSettingsCategory(document.querySelector('.settings-grid')?.dataset.settingsFilter||'appearance');$('autoRoute').checked=state.autoRoute;$('temperature').value=state.preferences.temperature;$('temperatureValue').textContent=Number(state.preferences.temperature).toLocaleString('cs-CZ',{minimumFractionDigits:1,maximumFractionDigits:1});$('contextSize').value=String(state.preferences.num_ctx);$('maxTokens').value=String(state.preferences.num_predict);$('threadCount').value=String(state.preferences.num_thread);if($('performanceProfile'))$('performanceProfile').value=state.performanceProfile;updatePerformanceHint();renderMessages();renderHistory();renderArchiveAndProjects();renderProjectSpaces();applyAgentComplexity();renderImageHistory();await loadProjectSpaces();await loadHardware();await refreshStatus();await refreshOllamaServiceButtons();refreshOpenAIStatus();await refreshComfyStatus();await refreshLocalMemoryUI();renderTelemetry()});
